"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["36141"],{79481(e){e.exports=JSON.parse('{"id":"FIN-532","slug":"tax","term":"Tax","also_known_as":[],"difficulty":"Beginner","definition":"A tax is a compulsory payment that individuals and businesses must make to the government, used to fund public services and government activities.","explanation":["Taxes pay for roads, schools, healthcare, defence, the legal system, pensions and much more. Unlike prices paid for goods, taxes are compulsory and are not directly linked to a specific service the taxpayer receives.","Taxes come in many forms. Income taxes are charged on earnings. Payroll or social security taxes fund pensions and benefits. Consumption taxes, such as sales tax and value-added tax, are added to the price of goods and services. Property taxes are charged on land and buildings. Corporate taxes are charged on company profits. Capital gains taxes apply to profits from selling assets.","Taxes can be direct, paid straight to the government by the person who owes them, such as income tax, or indirect, collected by businesses on the government\'s behalf, such as sales tax.","Taxes also shape behaviour. High taxes on tobacco discourage smoking, while tax relief on pension contributions encourages saving. Because tax rules vary greatly between countries and change frequently, understanding local rules is important for both personal and business decisions."],"note":"","total":1500,"prev":{"slug":"tariff","term":"Tariff"},"next":{"slug":"tax-advantaged-account","term":"Tax-Advantaged Account"}}')}}]);